using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Weil.ZetaBridge;

internal sealed class ActualThreeNodeFiniteSpectrumDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual three-node FiniteSpectrum", H("Actual three-node FiniteSpectrum"),
        Blocks(
            Paragraph(Text("Set tau=U/3+C/6, d=(U/3)(C/6)-(T/sqrt(18))^2 and Delta=(U/3-C/6)^2+4(T/sqrt(18))^2. Delta>=0, rhoPlus=(tau+sqrt(Delta))/2 and rhoMinus=(tau-sqrt(Delta))/2 satisfy rhoMinus<=rhoPlus, sum=tau and product=d.")),
            Paragraph(Text("Direct expansion of the actual finite matrix characteristic determinant yields (X-O)(X^2-tau X+d), then (X-rhoPlus)(X-O)(X-rhoMinus). The complex root multiset and the real eigenvalue multiset each have three entries with multiplicity, including coincident roots.")),
            Paragraph(Text("Matrix.IsHermitian.sort_roots_charpoly_eq_eigenvalues₀ identifies the complete descending list. Whenever rhoMinus<=O, its entries are [max(rhoPlus,O),min(rhoPlus,O),rhoMinus]. The top roots may tie.")),
            Paragraph(Text("For a=0, h>0, r!=0 and r^2<=1, evaluating the even characteristic quadratic at O gives -8h^2 r^2(5-r^2)(3-r^2)/15<0. The product identity then proves 0<rhoMinus<O<rhoPlus throughout this exterior range.")),
            Describe.Lean(DescribeId.Create("even-tau"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.evenTau"),
                H("evenTau"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def evenTau (g mu a r : ℝ) : ℝ := U g mu a r / 3 + ActualThreeNodeFiniteAlgebra.C g mu a r / 6"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("even-rad"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.evenRad"),
                H("evenRad"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def evenRad (g mu a r : ℝ) : ℝ :=\n  (U g mu a r / 3 - ActualThreeNodeFiniteAlgebra.C g mu a r / 6) ^ 2 +\n    4 * (T g mu a r / Real.sqrt 18) ^ 2"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rho-plus"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rhoPlus"),
                H("rhoPlus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rhoPlus (g mu a r : ℝ) : ℝ :=\n  (evenTau g mu a r + Real.sqrt (evenRad g mu a r)) / 2"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rho-minus"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rhoMinus"),
                H("rhoMinus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rhoMinus (g mu a r : ℝ) : ℝ :=\n  (evenTau g mu a r - Real.sqrt (evenRad g mu a r)) / 2"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("even-rad-nonneg"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.evenRad_nonneg"),
                H("evenRad nonneg"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma evenRad_nonneg (g mu a r : ℝ) : 0 ≤ evenRad g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rho-order"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rho_order"),
                H("rho order"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rho_order (g mu a r : ℝ) : rhoMinus g mu a r ≤ rhoPlus g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rho-sum"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rho_sum"),
                H("rho sum"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rho_sum (g mu a r : ℝ) :\n    rhoMinus g mu a r + rhoPlus g mu a r = evenTau g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("even-rad-trace-det"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.evenRad_trace_det"),
                H("evenRad trace det"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma evenRad_trace_det (g mu a r : ℝ) :\n    evenRad g mu a r = evenTau g mu a r ^ 2 - 4 * evenDet g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rho-product"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rho_product"),
                H("rho product"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rho_product (g mu a r : ℝ) :\n    rhoMinus g mu a r * rhoPlus g mu a r = evenDet g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rho-minus-eq-div"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.rhoMinus_eq_div"),
                H("rhoMinus eq div"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rhoMinus_eq_div (g mu a r : ℝ) (hp : rhoPlus g mu a r ≠ 0) :\n    rhoMinus g mu a r = evenDet g mu a r / rhoPlus g mu a r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-eigen"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finiteEigen"),
                H("finiteEigen"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("abbrev finiteEigen (g mu a r : ℝ) : Fin 3 → ℝ :=\n  (finiteMatrix_isHermitian g mu a r).eigenvalues₀"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("finite-charpoly-quadratic"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finite_charpoly_quadratic"),
                H("finite charpoly quadratic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma finite_charpoly_quadratic (g mu a r : ℝ) :\n    (finiteMatrix g mu a r).charpoly =\n      (X - Polynomial.C (O g mu a r : ℂ)) *\n        (X ^ 2 - Polynomial.C (evenTau g mu a r : ℂ) * X +\n          Polynomial.C (evenDet g mu a r : ℂ))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-charpoly"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finite_charpoly"),
                H("finite charpoly"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma finite_charpoly (g mu a r : ℝ) :\n    (finiteMatrix g mu a r).charpoly =\n      (X - Polynomial.C (rhoPlus g mu a r : ℂ)) *\n      (X - Polynomial.C (O g mu a r : ℂ)) *\n      (X - Polynomial.C (rhoMinus g mu a r : ℂ))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-roots"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finite_roots"),
                H("finite roots"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem finite_roots (g mu a r : ℝ) :\n    (finiteMatrix g mu a r).charpoly.roots =\n      {(rhoPlus g mu a r : ℂ), (O g mu a r : ℂ), (rhoMinus g mu a r : ℂ)}"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-spectrum-multiset"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finite_spectrum_multiset"),
                H("finite spectrum multiset"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem finite_spectrum_multiset (g mu a r : ℝ) :\n    (List.ofFn (finiteEigen g mu a r) : Multiset ℝ) =\n      {rhoPlus g mu a r, O g mu a r, rhoMinus g mu a r}"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-sorted-eq"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.finite_sorted_eq"),
                H("finite sorted eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem finite_sorted_eq (g mu a r : ℝ) (hmo : rhoMinus g mu a r ≤ O g mu a r) :\n    finiteEigen g mu a r =\n      ![max (rhoPlus g mu a r) (O g mu a r),\n        min (rhoPlus g mu a r) (O g mu a r), rhoMinus g mu a r]"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exceptional-characteristic-at-odd"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.exceptional_characteristic_at_odd"),
                H("exceptional characteristic at odd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma exceptional_characteristic_at_odd (g mu r : ℝ) :\n    O g mu 0 r ^ 2 - evenTau g mu 0 r * O g mu 0 r + evenDet g mu 0 r =\n      -8 * (g ^ 2 + mu) ^ 2 * r ^ 2 * (5 - r ^ 2) * (3 - r ^ 2) / 15"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exceptional-finite-order"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.exceptional_finite_order"),
                H("exceptional finite order"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem exceptional_finite_order (g mu r : ℝ) (hh : 0 < g ^ 2 + mu)\n    (hr : r ≠ 0) (hrsq : r ^ 2 ≤ 1) :\n    0 < rhoMinus g mu 0 r ∧ rhoMinus g mu 0 r < O g mu 0 r ∧\n      O g mu 0 r < rhoPlus g mu 0 r"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exceptional-finite-sorted"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteSpectrum.exceptional_finite_sorted"),
                H("exceptional finite sorted"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem exceptional_finite_sorted (g mu r : ℝ) (hh : 0 < g ^ 2 + mu)\n    (hr : r ≠ 0) (hrsq : r ^ 2 ≤ 1) :\n    finiteEigen g mu 0 r = ![rhoPlus g mu 0 r, O g mu 0 r, rhoMinus g mu 0 r]"))), DescribeRole.Theorem))));
}
